import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt


def task_func(s1, s2):
    if not isinstance(s1, pd.Series) or not isinstance(s2, pd.Series):
        raise TypeError("s1 and s2 must be pandas Series")

    intersection = set(s1.dropna().unique()) & set(s2.dropna().unique())

    combined = pd.DataFrame({
        "value": pd.concat([s1, s2], ignore_index=True),
        "series": ["s1"] * len(s1) + ["s2"] * len(s2),
    }).dropna(subset=["value"])

    fig, ax = plt.subplots()

    if not combined.empty:
        sns.swarmplot(
            data=combined,
            x="series",
            y="value",
            ax=ax,
        )

    for value in intersection:
        ax.axhline(value, color="red", linestyle="--")

    return ax, len(intersection)

def check(candidate):
    import pandas as pd

    print(candidate(
        pd.Series([1, 2, 3, 4]),
        pd.Series([3, 4, 5, 6])
    ))

    print(candidate(
        pd.Series([1, 1, 2, 2, 3]),
        pd.Series([1, 2, 2, 4])
    ))

    print(candidate(
        pd.Series([10, 20, 30]),
        pd.Series([40, 50, 60])
    ))

    print(candidate(
        pd.Series([1, None, 3, 3]),
        pd.Series([None, 3, 4])
    ))

    print(candidate(
        pd.Series(dtype=float),
        pd.Series(dtype=float)
    ))
check(task_func)
